truncate test.results;
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select test.expect_error($q$select * from public.casa_payment_plan(2::smallint,200,null)$q$,'42501');
select test.expect_error($q$select public.casa_record_payment_batch(gen_random_uuid(),2::smallint,200,'2030-03-20','cash',null,null,null,null)$q$,'42501');
select test.expect_error($q$select public.casa_record_payment_batch(gen_random_uuid(),1::smallint,0,'2030-03-20','cash',null,null,null,null)$q$,'22023');
select test.expect_error($q$select public.casa_record_payment_batch(gen_random_uuid(),1::smallint,'NaN','2030-03-20','cash',null,null,null,null)$q$,'22023');
select test.expect_error($q$select public.casa_record_payment_batch(gen_random_uuid(),1::smallint,'Infinity','2030-03-20','cash',null,null,null,null)$q$,'22023');
select test.expect_error($q$select public.casa_record_payment_batch(gen_random_uuid(),1::smallint,200,'2030-03-20','invalid',null,null,null,null)$q$,'22023');
select test.expect_error($q$select public.casa_record_payment_batch(gen_random_uuid(),1::smallint,200,'2030-03-20','qr',null,null,null,null)$q$,'22023');
select test.expect_error($q$select public.casa_record_payment_batch(gen_random_uuid(),1::smallint,200,'2030-03-20','qr','foreign/photo.png',null,null,null)$q$,'22023');
select test.expect_error($q$select public.casa_record_payment_batch(gen_random_uuid(),1::smallint,200,'2030-03-20','qr','00000000-0000-0000-0000-000000000002/missing.png',null,null,null)$q$,'22023');
select test.expect_error($q$select public.casa_record_payment_batch(gen_random_uuid(),1::smallint,200,'2030-03-20','cash',null,null,null,'20000000-0000-0000-0000-000000000004')$q$,'42501');
select public.casa_record_payment_batch('30000000-0000-0000-0000-000000000001',1::smallint,200,'2030-03-20','qr','00000000-0000-0000-0000-000000000002/deposit.png',null,null,null);
select test.check((select sum(balance)=240 from public.family_portal_debts()),'Pending deposit does not clear real family portal balances');
select test.check((select count(*)=1 and sum(amount)=200 and bool_and(status='pending') from public.payments),'One 200 Bs pending deposit with one receipt');
select test.check((select planned_allocation->0->>'concept'='Enero' and (planned_allocation->0->>'amount')::numeric=80 and (planned_allocation->1->>'amount')::numeric=80 and (planned_allocation->2->>'amount')::numeric=40 and planned_credit=0 from public.payment_batches),'Preview allocates 80/80/40 in oldest-first order');
select public.casa_record_payment_batch('30000000-0000-0000-0000-000000000001',1::smallint,200,'2030-03-20','qr','00000000-0000-0000-0000-000000000002/deposit.png',null,null,null);
select test.check((select count(*)=1 from public.payments),'Retry is idempotent');
select test.expect_error($q$select public.casa_record_payment_batch('30000000-0000-0000-0000-000000000001',1::smallint,201,'2030-03-20','qr','00000000-0000-0000-0000-000000000002/deposit.png',null,null,null)$q$,'22023');
select test.expect_error($q$select public.casa_record_payment_batch(gen_random_uuid(),1::smallint,200,'2030-03-20','qr','00000000-0000-0000-0000-000000000002/deposit.png',null,null,null)$q$,'22023');
select test.expect_error($q$select public.casa_review_payment_batch('30000000-0000-0000-0000-000000000001',true)$q$,'42501');
select test.expect_error($q$update public.payment_batches set amount=1$q$,'42501');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',false);
select test.check((select count(*)=0 from public.payment_batches),'Unrelated accounting family cannot read batch');
select test.expect_error($q$select public.casa_record_payment_batch('30000000-0000-0000-0000-000000000001',2::smallint,200,'2030-03-20','cash',null,null,null,null)$q$,'42501');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select test.check((select count(*)=1 from public.payment_batches),'Staff can review deposit');
select test.expect_error($q$select public.casa_review_payment_batch('30000000-0000-0000-0000-000000000001',null)$q$,'22023');
select set_config('test.fail_audit','on',false);
select test.expect_error($q$select public.casa_review_payment_batch('30000000-0000-0000-0000-000000000001',true)$q$,'P0001');
select set_config('test.fail_audit','off',false);
select test.check((select count(*)=1 and bool_and(status='pending') and sum(applied_amount)=0 from public.payments),'Failed audit rolls back entire approval and split');
-- Compatibility: reviewing the anchor through the old API reviews the entire deposit.
select public.review_payment('30000000-0000-0000-0000-000000000001',true);
select test.check((select status='approved' and amount=200 and applied_amount=200 and credit_amount=0 from public.payment_batches where id='30000000-0000-0000-0000-000000000001'),'Header stores authoritative approved totals');
select test.check((select count(*)=3 and sum(amount)=200 and sum(applied_amount)=200 and sum(credit_amount)=0 and count(distinct receipt_path)=1 from public.payments),'Approval splits 200 without duplicating money or receipt');
reset role;
select test.check(public.share_approved_paid('20000000-0000-0000-0000-000000000001')=80,'Oldest month cleared');
select test.check(public.share_approved_paid('20000000-0000-0000-0000-000000000002')=80,'Second month cleared');
select test.check(public.share_approved_paid('20000000-0000-0000-0000-000000000003')=40,'Third month receives remaining 40');
select test.check((select sum(amount_due-public.share_approved_paid(id))=40 from public.expense_shares where family_id=1),'Family still owes exactly 40');
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select test.expect_error($q$select public.review_payment('30000000-0000-0000-0000-000000000001',true)$q$,'22023');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select public.casa_record_payment_batch('30000000-0000-0000-0000-000000000002',1::smallint,50,'2030-03-20','cash',null,null,null,null);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select public.casa_review_payment_batch('30000000-0000-0000-0000-000000000002',false);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select test.check((select sum(balance)=40 and sum(amount_paid)=200 from public.family_portal_debts()),'Family portal uses the 80/80/40 split and returns exactly 40 pending');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select test.check((select status='rejected' from public.payment_batches where id='30000000-0000-0000-0000-000000000002'),'Entire deposit rejected');
reset role;
select test.check(public.share_approved_paid('20000000-0000-0000-0000-000000000003')=40,'Rejection does not reduce balance');
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select public.casa_record_payment_batch('30000000-0000-0000-0000-000000000003',1::smallint,50,'2030-03-20','cash',null,null,null,null);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',false);
select public.casa_review_payment_batch('30000000-0000-0000-0000-000000000003',true);
reset role;
select test.check((select balance=10 from public.family_credits where family_id=1),'Only true excess becomes 10 Bs credit');
select test.check((select sum(amount_due-public.share_approved_paid(id))=0 from public.expense_shares where family_id=1),'No outstanding debt remains before credit');
-- Reset only synthetic payment fixtures to exercise overlapping pending deposits.
truncate public.payments,public.payment_batches;
truncate public.family_credits;
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select public.casa_record_payment_batch('30000000-0000-0000-0000-000000000004',1::smallint,200,'2030-03-20','cash',null,null,null,null);
select public.casa_record_payment_batch('30000000-0000-0000-0000-000000000005',1::smallint,100,'2030-03-20','cash',null,null,null,null);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select public.casa_review_payment_batch('30000000-0000-0000-0000-000000000004',true);
select public.casa_review_payment_batch('30000000-0000-0000-0000-000000000005',true);
reset role;
select test.check((select sum(applied_amount)=240 and sum(credit_amount)=60 and sum(amount)=300 from public.payments),'Overlapping deposits recalculate to 240 applied and 60 credit');
select test.check((select balance=60 from public.family_credits where family_id=1),'Overlapping deposits credit once');
select test.check((select bool_and(public.share_approved_paid(id)<=amount_due) from public.expense_shares),'No share is overpaid');
-- Single-debt mode stays available and staff cash deposits are approved immediately.
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',false);
select public.casa_record_payment_batch('30000000-0000-0000-0000-000000000006',2::smallint,30,'2030-03-20','cash',null,'Parcial',null,'20000000-0000-0000-0000-000000000004');
select test.check((select status='approved' from public.payment_batches where id='30000000-0000-0000-0000-000000000006'),'Staff deposit auto-approved as existing workflow');
reset role;
select test.check(public.share_approved_paid('20000000-0000-0000-0000-000000000004')=30,'Single debt receives partial payment');
-- Legacy, non-batch cash API still approves and uses the same serialized reviewer.
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',false);
select public.record_payment_v7('20000000-0000-0000-0000-000000000004',10,'2030-03-20','cash',null,null,null);
reset role;
select test.check(public.share_approved_paid('20000000-0000-0000-0000-000000000004')=40,'Legacy non-batch payment remains compatible');
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000005',false);
select test.check((select count(*)=0 from public.payment_batches),'Restaurant cannot read family deposits');
select test.expect_error($q$select public.casa_record_payment_batch(gen_random_uuid(),3::smallint,10,'2030-03-20','cash',null,null,null,null)$q$,'42501');
select set_config('request.jwt.claim.sub','',false);
select test.expect_error($q$select public.casa_review_payment_batch(null,true)$q$,'42501');
select test.expect_error($q$select public.review_payment(null,true)$q$,'P0001');
reset role;
set role anon;
select test.expect_error($q$select public.casa_record_payment_batch(null,null,10,null,'cash',null,null,null,null)$q$,'42501');
select test.expect_error($q$select * from public.payment_batches$q$,'42501');
reset role;
-- Debt can become fully paid between submission and review: preserve the whole deposit as credit.
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',false);
select public.casa_record_payment_batch('30000000-0000-0000-0000-000000000007',2::smallint,50,'2030-03-20','cash',null,null,null,null);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',false);
select public.record_payment_v7('20000000-0000-0000-0000-000000000004',40,'2030-03-20','cash',null,null,null);
select public.casa_review_payment_batch('30000000-0000-0000-0000-000000000007',true);
select test.check((select applied_amount=0 and credit_amount=50 and amount=50 from public.payments where id='30000000-0000-0000-0000-000000000007'),'Already-settled debt preserves full incoming money as credit');
select test.check((select status='approved' from public.payment_batches where id='30000000-0000-0000-0000-000000000007'),'No-debt-at-review branch approves exactly once');
select test.expect_error($q$select public.casa_review_payment_batch('30000000-0000-0000-0000-000000000007',true)$q$,'22023');
select test.check((select count(*)=1 and sum(amount)=50 from public.payments where batch_id='30000000-0000-0000-0000-000000000007'),'No duplicate parts when all debt was already cleared');
reset role;
select test.check((select balance=50 from public.family_credits where family_id=2),'Whole-deposit credit is recorded once');
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',false);
select test.expect_error($q$select public.casa_record_payment_batch(gen_random_uuid(),2::smallint,50,'2030-03-20','cash',null,null,null,null)$q$,'22023');
reset role;
select json_build_object('batchPaymentChecks',count(*),'result','PASS') from test.results;
